class OpeningHoursListComponent {
    constructor(commonService) {
        this.commonService = commonService;
        this.displayData = [];
        this.pageIndex = 1;
        this.pageSize = 10;
        this.total = 0;
    }
    ngOnInit() {
        this.fetchData();
    }
    /* ---------- FETCH DATA ---------- */
    fetchData() {
        const paramsObj = '';
        this.commonService.getData(this.pageIndex, this.pageSize, 'opening-hours/adminAll', paramsObj).subscribe({
            next: (res) => {
                this.displayData = res.result.openingHours || [];
                this.total = res.result.totalCount || 0;
            },
            error: (err) => {
                console.error('Error fetching opening hours:', err);
            }
        });
    }
    /* ---------- DELETE ---------- */
    deleteItem(id) {
        if (!confirm('Are you sure you want to delete this record?'))
            return;
        this.commonService.deleteItem('/opening-hours', id).subscribe({
            next: () => {
                alert('Deleted successfully');
                this.fetchData();
            },
            error: (err) => {
                alert(err?.error?.message || 'Delete failed');
            }
        });
    }
    /* ---------- PAGINATION ---------- */
    onPageChange(pageIndex) {
        this.pageIndex = pageIndex;
        this.fetchData();
    }
}
