class TermsAndConditionsListComponent {
    constructor(commonService, router, notification) {
        this.commonService = commonService;
        this.router = router;
        this.notification = notification;
        this.displayData = [];
        this.pageIndex = 1;
        this.pageSize = 10;
        this.total = 0;
    }
    ngOnInit() {
        this.fetchData();
    }
    /* ---------- FETCH DATA ---------- */
    fetchData() {
        const paramsObj = '';
        this.commonService
            .getData(this.pageIndex, this.pageSize, 'terms-and-conditions/adminAll', paramsObj)
            .subscribe({
            next: (res) => {
                this.displayData = res.result.termsAndConditions;
                this.total = res.result.totalCount;
            },
            error: (err) => {
                console.error('Error fetching data:', err);
            },
        });
    }
    /* ---------- DELETE ---------- */
    deleteItem(id) {
        if (!confirm('Are you sure you want to delete this record?'))
            return;
        this.commonService.deleteItem('/terms-and-conditions', id).subscribe({
            next: () => {
                this.notification.success('Success', 'Deleted successfully');
                this.fetchData();
            },
            error: (err) => {
                this.notification.error('Error', err?.error?.message || 'Failed to delete');
            },
        });
    }
    /* ---------- PAGINATION ---------- */
    onPageChange(page) {
        this.pageIndex = page;
        this.fetchData();
    }
}
