  get journeyImages() {
    return this.workshopForm.get('journeyImage');
  }

  get includesArray() {
    return this.workshopForm.get('includes');
  }

  get defaultSlots() {
    return this.workshopForm.get('defaultSlots');
  }

  get options() {
    return this.workshopForm.get('options');
  }

  get nonAvailabilityDays() {
    return this.workshopForm.get('nonAvailabilityDays');
  }

  get moreDetailsArray() {
    return this.workshopForm.get('moreDetails');
  }

