class WorkshopListComponent {
    constructor(commonService, notification) {
        this.commonService = commonService;
        this.notification = notification;
        this.displayData = [];
        this.pageIndex = 1;
        this.pageSize = 10;
        this.total = 0;
        this.loading = false;
        this.searchInput = '';
    }
    ngOnInit() {
        this.getWorkshops();
    }
    getWorkshops() {
        this.loading = true;
        const paramsObj = {
            search: this.searchInput || undefined,
        };
        this.commonService.getData(this.pageIndex, this.pageSize, 'workshop/adminAll', paramsObj).subscribe({
            next: (res) => {
                this.displayData = res.result.workshops;
                this.total = res.result.totalCount;
                this.loading = false;
            },
            error: () => {
                this.notification.error('Error', 'Failed to load workshops');
                this.loading = false;
            }
        });
    }
    search() {
        this.pageIndex = 1;
        this.getWorkshops();
    }
    onPageChange(pageIndex) {
        this.pageIndex = pageIndex;
        this.getWorkshops();
    }
    deleteItem(id) {
        if (!confirm('Are you sure you want to delete this workshop?'))
            return;
        this.commonService.deleteItem('/workshop', id).subscribe({
            next: () => {
                this.notification.success('Success', 'Workshop deleted successfully');
                this.getWorkshops();
            },
            error: () => {
                this.notification.error('Error', 'Failed to delete workshop');
            }
        });
    }
}
